        if letter not in tiles_count or tiles_count[letter] < count:
            return False
    return True

def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    # Handle patterns like a*, b*, c*
    for j in range(2, n + 1):
        if p[j - 1] == '*':
