def count_vowel_strings(n):
    # Initialize the DP table
    dp = [[0]*5 for _ in range(n+1)]

    # Base case: there is one way to form a string of length 1 with each vowel
    for j in range(5):
        dp[1][j] = 1

    # Fill the DP table
    for i in range(2, n+1):
        for j in range(5):
            dp[i][j] = sum(dp[i-1][:j+1])

    # The result is the sum of all ways to form a string of length n ending with any vowel
    return sum(dp[n])

